class Solution {
public:
    string repeatLimitedString(string s, int repeatLimit) {
        int cnt[26]={0};for(char c:s) ++cnt[c-'a'];
        string ans;int i=25;
        while(i>=0) {
            if(!cnt[i]){--i;continue;}
            int take=min(cnt[i],repeatLimit);
            ans.append(take,char('a'+i));cnt[i]-=take;
            if(!cnt[i]) continue;
            int j=i-1;while(j>=0&&!cnt[j])--j;
            if(j<0) break;
            ans.push_back(char('a'+j));--cnt[j];
        }
        return ans;
    }
};
